    public boolean onUseItemOn(ItemStack heldItem, Player player, InteractionHand hand, Vec3 pos) {
        if (useMemoryCard(heldItem, player)) {
            return true;
        }
        return IPart.super.onUseItemOn(heldItem, player, hand, pos);
    }

